@has_request_variables
def join_bigbluebutton(
    request: HttpRequest,
    meeting_id: str = REQ(),
    password: str = REQ(),
    checksum: str = REQ(),
) -> HttpResponse:
    if settings.BIG_BLUE_BUTTON_URL is None or settings.BIG_BLUE_BUTTON_SECRET is None:
        return json_error(_("Big Blue Button is not configured."))
    else:
        try:
