        preexec_fn=os.setsid,
        close_fds=True,
    )
    logging.info("Started TLS tunnel, pid: %d", tunnel_proc.pid)
    temp_tls_state_file = write_tls_tunnel_state_file(
        fs_id,
        mountpoint,
