ATTR_SUFFIX = '.text_attr'
class DiamondTextAttr(object):
    def __enter__(self):
        if 'w' in self.mode:
            fd, name = mkstemp(suffix=ATTR_SUFFIX+'-tmp',
                               prefix='diamond-',
                               dir=os.path.dirname(self.path))
            self.file = os.fdopen(fd, self.mode)
            self.temp_name = name
        else:
            self.file = open(self.path, self.mode)
        return self

