class UserInterface:
    def run_update_report(self):
        """Update an existing bug with locally collected information."""
        if not self.crashdb.can_update(self.args.update_report):
            self.ui_error_message(
                _("Updating problem report"),
                _(
                    "You are not the reporter or subscriber of this "
                    "problem report, or the report is a duplicate or already "
                    'closed.\n\nPlease create a new report using "apport-bug".'
                ),
            )
            return False
        is_reporter = self.crashdb.is_reporter(self.args.update_report)
        if not is_reporter:
            r = self.ui_question_yesno(
                _(
                    "You are not the reporter of this problem report. It is "
                    "much easier to mark a bug as a duplicate of another than "
                    "to move your comments and attachments to a new bug.\n\n"
                    "Subsequently, we recommend that you file a new bug "
                    'report using "apport-bug" and make a comment in this bug '
                    "about the one you file.\n\nDo you really want to proceed?"
                )
            )
            if not r:
                return False
        self.report = apport.Report("Bug")
        if self.args.package:
            pkgs = [self.args.package.strip()]
        else:
            pkgs = self.crashdb.get_affected_packages(self.args.update_report)
        info_collected = False
        for p in pkgs:
            self.cur_package = p
            self.report["SourcePackage"] = p
            self.report["Package"] = p
            try:
                packaging.get_version(p)
            except ValueError:
                if not os.path.exists(
                    os.path.join(
                        apport.report.PACKAGE_HOOK_DIR, "source_%s.py" % p
                    )
                ):
                    print(
                        "Package %s not installed and no hook available,"
                        " ignoring" % p
                    )
                    continue
            self.collect_info(ignore_uninstalled=True)
            info_collected = True
        if not info_collected:
            self.ui_info_message(
                _("Updating problem report"),
                _("No additional information collected."),
            )
            return False
        self.report.add_user_info()
        self.report.add_proc_environ()
        self.add_extra_tags()
        del self.report["Date"]
        try:
            del self.report["SourcePackage"]
        except KeyError:
            pass
        if len(self.report) == 0:
            self.ui_info_message(
                _("Updating problem report"),
                _("No additional information collected."),
            )
            return False
        allowed_to_report = True
        response = self.ui_present_report_details(allowed_to_report)
        if response.report:
            self.crashdb.update(
                self.args.update_report,
                self.report,
                "apport information",
                change_description=is_reporter,
                attachment_comment="apport information",
            )
            return True
        return False
    def open_url(self, url):
        """Open the given URL in a new browser window.
        Display an error dialog if everything fails.
        """
        (r, w) = os.pipe()
        if os.fork() > 0:
            os.close(w)
            status = os.wait()[1]
            if status:
                title = _("Unable to start web browser")
                error = _("Unable to start web browser to open %s." % url)
                message = os.fdopen(r).readline()
                if message:
                    error += "\n" + message
                self.ui_error_message(title, error)
            try:
                os.close(r)
            except OSError:
                pass
            return
        os.setsid()
        os.close(r)
        try:
            try:
                run_as_real_user(["xdg-open", url])
            except OSError:
                webbrowser.open(url, new=True, autoraise=True)
                sys.exit(0)
        except Exception as error:
            os.write(w, str(error))
            sys.exit(1)
        os._exit(0)
def _command_output(
    command: list[str], env: typing.Optional[dict[str, str]] = None
) -> str:
    """Run command and capture its output.
    Try to execute given command (argv list) and return its stdout, or return
    a textual error if it failed.
    """
    try:
        sp = subprocess.run(
            command,
            check=False,
            encoding="UTF-8",
            env=env,
            errors="replace",
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            timeout=1800,
        )
    except subprocess.TimeoutExpired as error:
        raise OSError(
            f"Error: command {str(error.cmd)} timed out"
            f" after {error.timeout} seconds: {error.stdout.rstrip()}"
        ) from error
    if sp.returncode == 0:
        return sp.stdout.rstrip()
    raise OSError(
        "Error: command %s failed with exit code %i: %s"
        % (str(command), sp.returncode, sp.stdout.rstrip())
    )
