gs_windows_binary = None
def Ghostscript(tile, size, fp, scale=1):
    """Render an image using Ghostscript"""
    decoder, tile, offset, data = tile[0]
    length, bbox = data
    scale = int(scale) or 1
    orig_size = size
    orig_bbox = bbox
    size = (size[0] * scale, size[1] * scale)
    bbox = [bbox[0], bbox[1], bbox[2] * scale, bbox[3] * scale]
    import tempfile, os, subprocess
    file = tempfile.mktemp()
    command = ["gs",
               "-q",
               "-g%dx%d" % size,
               "-r%d" % (72*scale),
               "-dNOPAUSE -dSAFER",
               "-sDEVICE=ppmraw",
               "-sOutputFile=%s" % file,
            ]
    if gs_windows_binary is not None:
        if gs_windows_binary is False:
            raise WindowsError('Unable to locate Ghostscript on paths')
        command[0] = gs_windows_binary
    try:
        gs = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE)
        if bbox[0] != 0 or bbox[1] != 0:
            gs.stdin.write(("%d %d translate\n" % (-bbox[0], -bbox[1])).encode('ascii'))
        fp.seek(offset)
        while length > 0:
            s = fp.read(8192)
            if not s:
                break
            length = length - len(s)
            gs.stdin.write(s)
        gs.stdin.close()
        status = gs.wait()
        if status:
            raise IOError("gs failed (status %d)" % status)
        im = Image.core.open_ppm(file)
    finally:
        try: os.unlink(file)
        except: pass
    return im
class PSFile:
    def seek(self, offset, whence=0):
        self.char = None
        self.fp.seek(offset, whence)
    def read(self, count):
        return self.fp.read(count).decode('latin-1')
    def readline(self):
        s = b""
        if self.char:
            c = self.char
            self.char = None
        else:
            c = self.fp.read(1)
        while c not in b"\r\n":
            s = s + c
            c = self.fp.read(1)
        if c == b"\r":
            self.char = self.fp.read(1)
            if self.char == b"\n":
                self.char = None
        return s.decode('latin-1') + "\n"
class EpsImageFile(ImageFile.ImageFile):
    def _open(self):
        fp = PSFile(self.fp)
        s = fp.read(512)
        if s[:4] == "%!PS":
            offset = 0
            fp.seek(0, 2)
            length = fp.tell()
        elif i32(s) == 0xC6D3D0C5:
            offset = i32(s[4:])
            length = i32(s[8:])
            fp.seek(offset)
        else:
            raise SyntaxError("not an EPS file")
        fp.seek(offset)
        box = None
        self.mode = "RGB"
        self.size = 1, 1
        s = fp.readline()
        while s:
            if len(s) > 255:
                raise SyntaxError("not an EPS file")
            if s[-2:] == '\r\n':
                s = s[:-2]
            elif s[-1:] == '\n':
                s = s[:-1]
            try:
                m = split.match(s)
            except re.error as v:
                raise SyntaxError("not an EPS file")
            if m:
                k, v = m.group(1, 2)
                self.info[k] = v
                if k == "BoundingBox":
                    try:
                        box = [int(float(s)) for s in v.split()]
                        self.size = box[2] - box[0], box[3] - box[1]
                        self.tile = [("eps", (0,0) + self.size, offset,
                                      (length, box))]
                    except:
                        pass
            else:
                m = field.match(s)
                if m:
                    k = m.group(1)
                    if k == "EndComments":
                        break
                    if k[:8] == "PS-Adobe":
                        self.info[k[:8]] = k[9:]
                    else:
                        self.info[k] = ""
                elif s[0:1] == '%':
                    pass
                else:
                    raise IOError("bad EPS header")
            s = fp.readline()
            if s[:1] != "%":
                break
        while s[0] == "%":
            if len(s) > 255:
                raise SyntaxError("not an EPS file")
            if s[-2:] == '\r\n':
                s = s[:-2]
            elif s[-1:] == '\n':
                s = s[:-1]
            if s[:11] == "%ImageData:":
                [x, y, bi, mo, z3, z4, en, id] =\
                    s[11:].split(None, 7)
                x = int(x); y = int(y)
                bi = int(bi)
                mo = int(mo)
                en = int(en)
                if en == 1:
                    decoder = "eps_binary"
                elif en == 2:
                    decoder = "eps_hex"
                else:
                    break
                if bi != 8:
                    break
                if mo == 1:
                    self.mode = "L"
                elif mo == 2:
                    self.mode = "LAB"
                elif mo == 3:
                    self.mode = "RGB"
                else:
                    break
                if id[:1] == id[-1:] == '"':
                    id = id[1:-1]
                while True:
                    s = fp.readline()
                    if not s:
                        break
                    if s[:len(id)] == id:
                        self.size = x, y
                        self.tile2 = [(decoder,
                                       (0, 0, x, y),
                                       fp.tell(),
                                       0)]
                        return
            s = fp.readline()
            if not s:
                break
        if not box:
            raise IOError("cannot determine EPS bounding box")
