            "small": 128,
            "floppy": 128,
            "hurd": 128,
        }.get(fstype, 256)
        total_inodes_size = total_inodes * inode_size * 1e-9
        avail = int(avail[:-2]) * 1e-6
        total = int(size[:-2]) * 1e-6 + total_inodes_size
        used = total - avail
        host_info = {
            "disk_info": {
                "used_GB": int(used),
                "avail_GB": int(avail),
                "used_pcent": (used / total) * 100,
            }
        }
        return host_info
