        otherinfo += struct.pack('>I', len(apu))
        otherinfo += apu
        apv = base64url_decode(headers['apv']) if 'apv' in headers else b''
        otherinfo += struct.pack('>I', len(apv))
        otherinfo += apv
        otherinfo += struct.pack('>I', bitsize)
