        settings_keys = key.split('-')
        if isinstance(value, list) and len(value) == 1 and settings_keys[-1] not in array_keys:
            value = value[0]
            if value in empty_values and value != '':
                value = None
        if settings_keys[-1] in array_keys and value[0] in empty_values:
            value = []
