                        self.im = self.im.convert("RGBA", Image.Dither.FLOYDSTEINBERG)
                        self.mode = "RGBA"
                        del self.info["transparency"]
                    else:
                        self.mode = "RGB"
                        self.im = self.im.convert("RGB", Image.Dither.FLOYDSTEINBERG)
